INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('chuan-ti', 'Ch''uan Ti', 'demon', 'rifts', 0, 'Anarchist (45%), Miscreant (20%), Diabolic (15%) or Aberrant (20%)', '{"IQ":"1D6+6","ME":"1D6+8","MA":"1D6","PS":"1D6+20","PP":"1D6+18","PE":"1D6+16","PB":"1D6","Spd":"2D6+40"}', NULL, NULL, '2D6x10+90', '1D6x10+60+PE', NULL, 'Also known as the Earth Hound. Race: a lesser demon. P.S. is Supernatural. M.D.C. +20 per level of experience. Spd is 30-36 mph (48 to 57.6 km). Equivalent level 1D6+1. Killed only by drowning or at 50 M.D.C. below zero, when it turns to a stone statue that must be melted down or it rises the next night.', NULL, 13, '{"attacks":5,"initiative":2,"strike":1,"parry":1,"dodge":2,"disarm":1,"pull":3,"roll":2}', 'The dodge is automatic. Two attacks per melee by magic. +1 to entangle; +2 to disarm and entangle with the tongue. +1 save vs all magic; +3 save vs Horror Factor and possession. Throws spears and stones twice the usual distance.', 'Speaks all languages, reads none. Basic Math 80%, Blend 60%, Camouflage 75%, Climb 98%/92%, Horsemanship: Exotic Animals 70%/60% (the Monkey-Wolf included), Intelligence 75%, Land Navigation 95%, Lore: Faerie 80%, Lore: Cattle and Animals 90%, Prowl 70%, W.P. Blunt, W.P. Spear, four Wilderness skills of choice 75%. Skills do not improve.', 'Nightvision 600 ft (183 m), sees the invisible. Runs, hunts and fights 18 hours without tiring; sleeps four hours in 24. Climbs rough surfaces at running speed, 60% +2% per level. Immune to S.D.C. weapons other than silver, and to disease and all heat and fire; lightning and electricity do half damage. Bio-regeneration: 3D6 M.D.C. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi; blown apart, it is whole again by the next nightfall. Prehensile tongue, 4 ft (1.2 m): grabs and entangles, wields ancient weapons at half bonuses and guns at -6, and does simple skills at half proficiency in twice the time. Alters its scent to hide (flowers, pine, or a fox, dog, tiger, deer, horse or rabbit), to lure (a female in heat, meat, peaches, ginger) or to frighten (death, musk, smoke, sulfur). VULNERABILITIES: S.D.C. silver does its damage as M.D. It cannot swim: fully under water it sinks and in 1D4+4 minutes becomes inert like stone, waking on its second night back on dry land; water magic does normal damage. Full damage from most M.D. weapons, psionics and magic.', 'Invocations: Fireblast (8), Fire Bolt (7), Fire Ball (10), Power Weapon (35), Sheltering Force (20), Spoil (30), Tame Beast (35, half the usual cost). Earth Elemental: Animate Plants (10), Chameleon (5), Chasm (25), Create Wood (5+), Crumble Stone (10), Dust Storm (5), Earth Rumble (10), Mystic Fulcrum (3), Repel Animals (10), Rock to Mud (6), River of Lava (25, half the usual cost), Rot Wood (4), Suspended Animation (80), Throwing Stones (4), Travel Through Walls (20). Demonic curses: none.', 'None', '6-7 ft (1.8 to 2.1 m); it crouches and looks shorter', '200-300 lbs (90 to 135 kg)', 'Unknown; presumed immortal', 'Throughout China and Southeast Asia, forests and mountains most of all; now and then Mongolia, Russia, Japan and India', 'Accepts service under stronger demons and gods, good or evil, for a hunt or two or for centuries', 'None by hatred: mortals and animals are prey, hunted for food, sport or on a master''s order. Hates being made a fool of', NULL, 'A hunched, tusked demon with a monkey''s face, bark-like skin and a dog''s legs, made to track and run down prey. It serves stronger masters as scout and hound and does not kill for pleasure.', 'Rifts World Book 24: China 1 p.84-86'),
('falcon-demon', 'Falcon Demon', 'demon', 'rifts', 0, 'Anarchist (30%), Miscreant (30%), Diabolic (30%) or Aberrant (10%)', '{"IQ":"1D6+8","ME":"1D6+8","MA":"1D6+10","PS":"1D6+24","PP":"1D6+18","PE":"1D6+16","PB":"1D6+8","Spd":"1D6+16"}', NULL, NULL, '1D6x10+60', '1D4x10+45', NULL, 'Race: a lesser demon. P.S. is Supernatural. M.D.C. is the main body; each wing has 3D6+40. Spd is on the ground; flying Spd is 110 (75 mph/120 km). Equivalent level 1D4. 70% are male. Killed at 30 M.D.C. below zero.', NULL, 14, '{"attacks":6,"initiative":2,"strike":2,"parry":3,"dodge":4,"disarm":2,"pull":3,"roll":4}', 'A spell counts as three attacks. +1 save vs all magic, +3 save vs illusions, +4 save vs Horror Factor, +1 save vs possession. As a firefly: +7 dodge, +10% Prowl.', 'Speaks all languages, reads none. Acrobatics 95%, Basic Math 90%, Climb 95%/90%, Falconry 80%, Identify Plants and Fruit 80%, Land Navigation 90%, Recognize Weapon Quality 75%, W.P. Pole Arm or Spear, one W.P. of choice (Archery allowed), two Wilderness skills of choice 60%. Skills do not improve.', 'A hawk''s sight: picks out a rabbit at two miles (3.2 km). Nightvision 1000 ft (305 m), sees the invisible. Leaps 20 ft (6.1 m) up and 100 ft (30.5 m) across; climbs at full speed, 92%. Immune to S.D.C. weapons other than ivory and bone, and to disease; cold does half damage. Bio-regeneration: 1D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Sleeps five hours in 24. Flies at 75 mph (120 km) and dives at twice that; glides silently at half speed (as Prowl 66%). A wing at zero M.D.C. grounds it for 48 hours. Firefly form, at night only, and the only form in which it can lay its curses: flies 10 mph (16 km). VULNERABILITIES: S.D.C. ivory or bone does its damage as M.D. Sunlight, or Globe of Daylight after one minute, shows its true nature and stops both the change and the curses. Burning incense keeps it 100 yards away. Magic, psionics and M.D. weapons do normal damage.', 'Armor of Ithan (10), Blinding Flash (1), Breathe Without Air (5), Call Lightning (15), Cloud of Smoke (2), Distant Voice (10), Electric Arc (8), Featherlight (10), Lantern Light (1), Light Target (6), Lightning Arc (30), Magic Pigeon (20). Demonic curses: Pestilence/Locusts and Animal Disease, on a person or a parcel of land.', 'None', '6-7 ft (1.8 to 2.1 m)', '120-160 lbs (54 to 72 kg)', 'Presumed immortal', 'Throughout China; fewer in the forests and mountains of Russia, Japan and India', 'Serves the Yama Kings, Demon Lords, dark gods and evil dragons', 'Mortals, whom it would see enslaved; great heroes and warriors most of all', NULL, 'A winged warrior with a hawk''s beak that serves demon armies as soldier and courier. It is obedient and sociable, fights with pole arms, and at night can shrink into a firefly to lay its curses.', 'Rifts World Book 24: China 1 p.86-88'),
('fox-faerie', 'Fox Faerie', 'demon', 'rifts', 0, 'Miscreant (40%), Diabolic (45%) or Aberrant (15%)', '{"IQ":"1D6+9","ME":"1D6+10","MA":"1D6+20","PS":"1D6+18","PP":"1D6+12","PE":"1D6+10","PB":"1D6+22","Spd":"1D6+30"}', NULL, NULL, '2D6x10+PE', '1D6x10+60', 'MEx2', 'Race: no faerie at all, a lesser demon; not the Fox Spirit. P.S. is Supernatural. M.D.C. +2D6 per level of experience. Spd is about 22 mph (35 km). P.B. is never under 23 in human form. Daylight halves M.D.C., cuts the physical attributes by 20% and makes its P.S. ordinary. Equivalent level 1D6+1. 80% are female. Killed at 20 M.D.C. below zero, and back with the next red or orange moon unless the tail is cut off and burned.', NULL, 13, '{"attacks":6,"initiative":1,"strike":2,"pull":5,"roll":3}', 'Two attacks per melee by magic. +1 save vs all magic, +3 save vs illusions, +3 save vs Horror Factor and possession. Drunk, its combat bonuses are halved and it has two attacks fewer.', 'Speaks all languages, reads none. Basic Math 80%, Climb 60%/50%, Concealment 80%, Dance 90%, Sing or Poetry 80%, Intelligence 70%, Land Navigation 75%, Palming 80%, Seduction 80%, Streetwise 70%, Skin and Prepare Animal Hides 75%, Swim 75%, three Domestic or Technical skills of choice 60%. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Leaps 10 ft (3 m) up and 20 ft (6.1 m) across. Immune to S.D.C. weapons other than bamboo, and to disease and bad meat. Bio-regeneration: 2D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Nocturnal; sleeps from noon to nightfall. Every power works in either shape. Human form at will: an attractive adult. Dynamic Attraction, 15 ft (4.6 m) radius: save 16+ (M.D. non-humans and the supernatural +2) or -10% skills, -2 to save vs Hypnotic Suggestion and mind control, and -2 initiative and combat bonuses for the first round. Euphoric Embrace: save 16+ (-2 if already attracted) or stay oblivious while one arm holds the victim, and for 1D4 rounds after. Kiss of Death: each kiss, one attack, drains 3D6 Hit Points past any S.D.C.; forced on an unwilling victim it costs two attacks, drains 2D6 and leaves the demon unable to parry or dodge. Every two Hit Points taken give it 1 M.D.C. for two hours, up to triple its normal total. A victim who loses 70% has attacks, Spd, P.S. and combat bonuses halved for 1D6x10+20 minutes. VULNERABILITIES: bamboo weapons do double their S.D.C. as M.D. Weak by day, as above. Magic, psionics, magic and M.D. weapons do normal damage. Poison, potions and drink affect it, and it loves alcohol.', 'Agony (20), Calling (8), Chameleon (6), Charm (12), Charismatic Aura (10), Cleanse (6), Concealment (6), Detect Concealment (6), Invisibility: Simple (6), Lantern Light (1). Demonic curses: none.', 'Major Psychic: Deaden Pain (4), Healing Touch (6), Hypnotic Suggestion (6), Mind Block (4), Psychic Diagnosis (4), Psychic Surgery (14), Suppress Fear (8)', '5-6 ft (1.5 to 1.8 m)', '90-130 lbs (40.5 to 58.5 kg)', 'Presumably immortal', 'Throughout China and Southeast Asia; now and then Mongolia, Russia and Japan', 'Evil beings and clever monsters, evil dragons above all; keeps love-struck human underlings; serves the Yama Kings and greater demons', 'Mortals are playthings; it likes to ruin beautiful people and things and to bring down heroes. Dislikes Fox Spirits', NULL, 'A fox-headed, furred demon that walks as a strikingly attractive human to seduce, rob and kill. Its kiss drains the life from its victims.', 'Rifts World Book 24: China 1 p.88-91'),
('headless-one', 'Headless One', 'demon', 'rifts', 0, 'Miscreant (40%), Diabolic (40%) or Aberrant (20%)', '{"IQ":"1D6+10","ME":"1D6+10","MA":"1D6+10","PS":"1D6+19","PP":"1D6+12","PE":"1D6+24","PB":"1D4","Spd":"1D6+10"}', NULL, NULL, '2D4x10+PE', '4D6x10+66', NULL, 'Race: a lesser demon. P.S. is Supernatural. Sunlight, or Globe of Daylight after one minute, halves M.D.C., P.P.E. and attacks and stops its change of form and its curses. Equivalent level 1D4. Always male. At zero M.D.C. it turns to vapor and returns with the next fog, mist or storm; it is killed only at 10 M.D.C. or less with a dozen orchid petals forced into its mouth.', NULL, 15, '{"attacks":4,"strike":1,"parry":1,"dodge":3}', 'A spell counts as two attacks. The dodge may be a turn to mist before the blow lands. +8 save vs Horror Factor, +3 save vs possession; its P.E. gives a large bonus to save vs magic.', 'Speaks all languages, reads none. Basic Math 90%, Brewing 90%, Biology 90%, Chemistry 80%, Holistic Medicine 70%, Lore: D-Bees 60%, Prowl 50%, Animal Husbandry 60%, Land Navigation 70%, Identify Plants and Fruit 80%, two Technical or Science skills of choice 60%. Skills do not improve.', 'Keen sight, nightvision 400 ft (122 m), sees the invisible. Immune to S.D.C. weapons, disease, poison and cold; man-made M.D. weapons and explosives do half damage. Bio-regeneration: 1D4x10 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Usually lives in a swamp and comes out at night or in fog and storm. Green Mist form, one action: half speed or on the wind, untouchable but unable to attack or use powers, +10% Prowl, one attack to re-form. Breath of disease (one attack, once per person per night): save 16+ vs non-lethal poison or hold the breath for 30 seconds, else one illness for 1D4+1 days (Pox, Fever, Stomach Sickness, Headaches or a Minor Disorder). Breath of wind: as Wind Rush at 5th level. Breath of life: raises a dead mortal whose body it has, at a price: the demon shares the memories, takes 10% of the person''s P.P.E. for good, and the person comes back a level lower and one step worse in alignment; undoing the change takes 1D4+1 years, 60% accept it and 20% slip further. VULNERABILITIES: weak in sunlight, as above. Magic, psionics and magic weapons do normal damage; other M.D. weapons half. The scent of orchids keeps it 100 yards off; it cannot cross a line of orchid petals or harm anyone wearing a visible orchid (+1 to save if the flower is tucked away).', 'Healing: Cure Illness (15), Cure Minor Disorders (10), Exorcism (30), Heal Wounds (10), Greater Healing (30), Lifeblast (15), Negate Poison (5), Purge Other (100), Purge Self (70), Restore Life (275), Restore Limb (80), Restoration (750), Stone to Flesh (30), Sustain (12). Others: Armorbane (100), Breathe Without Air (5), Distant Voice (10), Commune with Spirits (25), Impervious to Fire (5), Impervious to Poison (5), Life Drain (25), Mental Blast (15), Reflection (7). Demonic curses: Barrenness and Feebleness.', 'None', '5-6 ft (1.5 to 1.8 m)', '180-200 lbs (81 to 90 kg)', 'Presumed immortal', 'Throughout China; fewer in Russia, Japan and India', 'Helps anyone for food, favours or amusement; may be pressed into service by the Yama Kings, Demon Lords, Greater Demons, dark gods and evil dragons; drawn to Necromancers and death cults', 'Humans are fodder and playthings; it feels kinship with no one and keeps to itself', NULL, 'A hairy, neckless figure with eyes in its chest and a grinning mouth at its belly. It sells potent healing, even a return from death, at a cruel price, and breathes sickness on those who cross it.', 'Rifts World Book 24: China 1 p.91-93'),
('long-armed-giant', 'Long-Armed Giant', 'demon', 'rifts', 0, 'Anarchist (35%), Miscreant (50%), Diabolic (10%) or Aberrant (5%)', '{"IQ":"1D6+7","ME":"1D6+7","MA":"1D6+3","PS":"1D6+34","PP":"1D6+17","PE":"1D6+17","PB":"1D6+1","Spd":"1D6+17"}', NULL, NULL, '2D6x10+70', '1D4x10+45', NULL, 'Race: a lesser demon. P.S. is Supernatural. M.D.C. is the main body; each arm has 1D6x10+35 and each hand 1D4x10+17. Equivalent level 1D6. 70% are male. Killed at 30 M.D.C. below zero, when it curls into a ball of rotten wood around a seed and is reborn at the end of spring unless the seed is dug out and burned. As a white stag: Spd tripled.', NULL, 12, '{"attacks":4,"strike":1,"dodge":1,"disarm":2,"pull":3,"roll":1}', 'A spell counts as three attacks. +6 save vs Horror Factor, +5 save vs possession. As a white stag: +2 attacks, +1 strike, +2 parry, +2 dodge. In smoke it is blind: -10 to strike, parry and dodge. A grip is broken only by a combined ordinary P.S. of 75 or a Supernatural P.S. equal to its own.', 'Speaks all languages, reads none. Basic Math 90%, Blend 60%, Climb 90%/80%, Dowsing 90%, Holistic Medicine 55%, Identify Plants and Fruit 90%, Land Navigation 98%, Lore: Demons and Monsters 60% (90% for those of nature), Lore: Faerie 75%, Preserve Food 90%, Track Animals 80%, Track Humanoids 70%, two Wilderness skills of choice 60%. Skills do not improve.', 'A hawk''s sight: picks out a rabbit at two miles (3.2 km). Nightvision 1000 ft (305 m), sees the invisible. Floats on water; climbs at half Spd. Arms reach 30 ft (9.1 m) and a hand can lift a mid-sized car. Immune to all S.D.C. weapons other than stag or deer bone and antler, and to disease, poison, electricity, lightning and cold; M.D. weapons do half damage. Bio-regeneration: 1D6 M.D. each melee round (double at ley lines or wherever negative energy gathers). Tree form, by day only: a 100 ft (30.5 m) tree aware of everything within 300 yards, unable to attack. Giant White Stag form, day or night: 7 ft (2.1 m) at the shoulder, leaps 20 ft (6.1 m) up and 60 ft (18.3 m) across. Numbing Cold Breath: one minute, two attacks, a 20 ft (6.1 m) radius up to 100 ft (30.5 m) away; those vulnerable to cold lose initiative and one attack. Its tears bring rain for 1D4 hours over 1D6 miles (1.6 to 9.6 km) per level. Eats 2D6 mortals a week and can fast for six weeks. VULNERABILITIES: S.D.C. weapons of stag or deer bone and antler do their damage as M.D. S.D.C. fire does 4D6 M.D. and M.D. fire double; fire is H.F. 9 to it, a forest fire H.F. 16. Magic and psionics do normal damage.', 'Breathe Without Air (5), Call Lightning (15), Chameleon (6), Cleanse (6), Create Water (15), Create Wood (10+), Distant Voice (10), Energy Bolt (5), Heavy Breathing (5), Illusory Forest (45+), Influence the Beast (12), Lantern Light (1), Manipulate Objects (2+), Orb of Cold (6), Repel Animals (7), Wall of Wind (40), Wave of Frost (6), Wind Rush (20). Demonic curses: Drought only, on a person or a parcel of land.', 'None', '30 ft (9.1 m)', '4000-6000 lbs (1800 to 2700 kg)', 'Presumed immortal', 'The forests of China; once in a while those of Russia and Japan', 'Faerie Folk good and evil; Fox Spirits and One-Horned Goblins may befriend it; alone, with 1D4 of its kind or with 1D4+1 small allies; may be pressed into service by the Yama Kings and other greater powers', 'Mortals, whom it eats; Fire Elementals and beings of fire. It cares only for the forest', NULL, 'A gaunt, pale giant whose arms hang to the ground and whose joints crack like fireworks, easily taken for a statue or a tree. It guards the forest, helps its creatures and kills the humans who enter.', 'Rifts World Book 24: China 1 p.93-95'),
('ma-tou', 'Ma T-ou', 'demon', 'rifts', 0, 'Anarchist (10%), Miscreant (30%), Diabolic (10%) or Aberrant (50%)', '{"IQ":"1D6+9","ME":"1D6+10","MA":"1D6+12","PS":"1D6+29","PP":"1D6+20","PE":"1D6+20","PB":"1D6+5","Spd":"1D6+49"}', NULL, NULL, '1D6x10+50', '1D6x10+45', 'ME+12', 'Also known as the Horse. Race: a lesser demon. P.S. is Supernatural. Spd is about 35 mph (56 km), doubled as a white steed. Equivalent level 1D4. 70% are male. Killed at 30 M.D.C. below zero.', NULL, 12, '{"attacks":5,"initiative":2,"strike":2,"parry":3,"dodge":4,"disarm":2,"pull":3,"roll":4}', 'A spell counts as two attacks. +1 save vs all magic, +3 save vs illusion, +4 save vs Horror Factor, +1 save vs possession. Small blades (knife, cleaver, throwing spike, short sword): +3 strike, +2 parry, +3 strike thrown. As a white steed: +1 attack, +3 dodge. Other weapons and guns with no bonus; one of the few demons willing to use modern arms.', 'Speaks all languages, reads none. Basic Math 70%, Climb 70%/60%, Identify Plants and Fruit 80%, Land Navigation 90%, Lore: Cattle and Animals 70%, Recognize Weapon Quality 70%, Rope Works 70%, Whittling and Sculpting 50%, two Espionage or Wilderness skills of choice 50%. Skills do not improve.', 'Sharp sight: picks out a rabbit at two miles (3.2 km). Nightvision 1000 ft (305 m), sees the invisible. Leaps 15 ft (4.6 m) up and 30 ft (9.1 m) across. Immune to S.D.C. weapons other than silver, and to disease; heat and fire do half damage. Bio-regeneration: 2D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Sleeps four hours in 24. White Steed form, day or night: a large white horse with burning eyes, 6 ft (1.8 m) at the shoulder; breathes fire 100 ft (30.5 m), one attack per breath; immune to M.D. fire; leaps 30 ft (9.1 m) up and 90 ft (27.4 m) across. VULNERABILITIES: S.D.C. silver does its damage as M.D. Magic, psionics and M.D. weapons do normal damage. Cold and ice magic do 50% more.', 'Ballistic Fire (25), Deflect (10), Distant Voice (10), Featherlight (10), Fists of Fury (10+), Lightblade (20), Magic Shield (6), Ricochet Strike (12), Spinning Blades (20), Targeted Deflection (15), Thunder Clap (4), Light Target (6), Watchguard (10). Demonic curses: none.', 'Minor Psychic: Alter Aura (2), Death Trance (1), Mask P.P.E. (4), Mind Block (4)', '6-7 ft (1.8 to 2.1 m)', '120-160 lbs (54 to 72 kg)', 'Presumed immortal', 'China; fewer in Russia, Mongolia and India', 'Falcon Demons, Goat Demons, Ox-Heads and Monkey-Wolves; respects strength, honour and loyalty, even in a human warrior; serves the Yama Kings, Demon Lords, dark gods, sorcerers and evil dragons when it believes in the cause', 'Mortals, whom it would see enslaved; heroes and great warriors are rivals to test', NULL, 'A horse-headed demon soldier, strong, quick and tireless, that makes a good sergeant. It fights hard for a cause it believes in and deserts or rebels when thrown away or ruled cruelly.', 'Rifts World Book 24: China 1 p.95-96'),
('monkey-wolf', 'Monkey-Wolf', 'demon', 'rifts', 0, 'Unprincipled (2%), Anarchist (10%), Miscreant (10%) or Aberrant (78%)', '{"IQ":"1D6+9","ME":"1D6+10","MA":"1D6+16","PS":"1D6+24","PP":"1D6+16","PE":"1D6+20","PB":"1D6+8","Spd":"2D6+60"}', NULL, NULL, '2D6x10+70', '6D6+PE', 'MEx3', 'Race: a lesser demon. P.S. is Supernatural. Spd is 42-50 mph (67.2 to 80 km). Equivalent level 1D4+3. Male or female, 50% each. Killed at 20 M.D.C. or more below zero. The attribute lines on printed 97 are white on black and missing from the OCR; they were read off a render.', NULL, 12, '{"attacks":5,"initiative":2,"strike":1,"parry":1,"dodge":2,"disarm":2,"pull":4}', 'The dodge is automatic and uses no attack. +2 save vs possession, +6 save vs Horror Factor. The tail wields ancient weapons at half bonuses and guns at -4.', 'Speaks all languages, reads none. Basic Math 90%, Climb 80%/20%, Detect Ambush 80%, Intelligence 80%, Land Navigation 90%, Prowl 70%, Seduction 55%, Streetwise 60%, Swim 75%, Track 70%, Trap/Mine Detection 60%, three Wilderness and three Science or Technical skills of choice 70%. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Leaps 10 ft (3 m) up and 20 ft (6.1 m) across, half again at a run. Tracks people and animals by smell, 70% +2% per level, +12% on a blood scent. Immune to S.D.C. weapons other than bone and teeth, and to disease and bad meat; S.D.C. cold does nothing and M.D. cold half. Bio-regeneration: 2D6 M.D. each melee round (double at ley lines or wherever negative energy gathers). A night hunter, though it can go out by day. Human form, at night only and for one hour: an attractive, golden-haired, green-eyed adult. Wolf form, at night only: an ordinary grey wolf. Its tail holds and carries, and does skills at half proficiency in twice the time. Runs on the air at full Spd up to 20 ft (6.1 m) high; with a following wind 10% faster on a breeze, 30% when the wind is stiff (to 20 mph/32 km), 50% when it gusts at 21 mph (33.6 km) or more, as high as 2000 ft (610 m); against a wind over 20 mph its speed is halved and its ceiling is 200 ft (61 m). Eats its prey raw, bones and all. VULNERABILITIES: S.D.C. weapons of bone or teeth do their damage as M.D. M.D. weapons, fire, magic and psionics do normal damage. A follower by nature, it serves fools and tyrants to the death.', 'None. Demonic curses: none.', 'Major Psychic: Detect Psionics (6), Deaden Senses (4), Death Trance (1), Mind Block (4), Read Dimensional Portal (6), Sense Evil (2), Sense Magic (3), Sixth Sense (2)', '5-6 ft (1.5 to 1.8 m) at the shoulder, 6-8 ft (1.8 to 2.4 m) long, plus tail', '600-800 lbs (270 to 360 kg)', 'Unknown; at least 1000 years, perhaps immortal', 'China, in the service of many Yama Kings; also Mongolia and Russia, now and then the rest of Asia, India and Africa', 'Those it respects or fears: Greater Demons, Demon Lords, dark gods and the Yama Kings, and now and then a human, hero, warrior monk, dragon or avatar. Alone, it runs in pairs or packs of 3-8', 'Mortals and champions of light; it has no respect for the weak', NULL, 'A demon with a wolf''s body and a golden monkey''s head and tail, as clever as a person and often used by larger demons as a talking mount or scout. It hunts well in a pack, yields to a stronger master and keeps its word.', 'Rifts World Book 24: China 1 p.97-98'),
('ox-head-demon', 'Ox-Head Demon', 'demon', 'rifts', 0, 'Anarchist (10%), Miscreant (30%), Diabolic (20%) or Aberrant (40%)', '{"IQ":"1D6+1","ME":"1D6","MA":"1D6+1","PS":"2D4+39","PP":"1D6+10","PE":"1D6+24","PB":"1D6+2","Spd":"1D6+40"}', NULL, NULL, '4D6x10+PE', '6D6+PE', NULL, 'Race: a lesser demon. P.S. is Supernatural. Spd is about 30 mph (48 km), doubled as a black bull. Equivalent level 1D4. Male only. Shackled, chained or yoked, its physical attributes and attacks are halved, its bonuses cut by two thirds and it cannot change form. Killed at 60 M.D.C. below zero.', NULL, 12, '{"attacks":5,"initiative":3,"strike":3,"parry":3,"dodge":4,"disarm":2,"pull":3,"roll":4}', 'A spell counts as two attacks. +1 save vs all magic, +3 save vs illusion, +4 save vs Horror Factor, +1 save vs possession. Its hearing halves the penalties for darkness or blindness (-5). As a black bull: +1 attack, +1 strike.', 'Speaks all languages, reads none. Animal Husbandry 80%, Branding 70%, Climb 60%/50%, General Repair and Maintenance 70%, Herding Cattle 80%, Land Navigation 50%, Lore: Cattle and Animals 80%, Masonry 70%, Mining 60%, Rope Works 60%. Skills do not improve.', 'Sharp, polarised sight that glare cannot blind; nightvision 100 ft (30.5 m). Immune to S.D.C. weapons other than silver, and to disease; cold does half damage. Bio-regeneration: 2D6 M.D. each melee round (triple at ley lines or wherever negative energy gathers), not at all in places of positive chi. A creature of the day; sleeps from 1 to 5 in the morning. Black Bull form, day or night: 6 ft (1.8 m) at the shoulder, eyes crackling green; eye bolts reach 1000 ft (305 m), one attack each; immune to M.D. electricity; leaps 10 ft (3 m) up and 20 ft (6.1 m) across. Its charge knocks down foes up to 30 ft (9.1 m) tall, who lose initiative and three attacks and have a 01-60% chance to drop what they hold. Lifts and carries 100 times its P.S. Works or fights 72 hours without sleep, then loses 10% of its physical attributes a day; with two hours'' rest a day it never stops. VULNERABILITIES: dull, gullible and quick to rage. S.D.C. silver does its damage as M.D. Shackles sap it, as above. Fire magic does 50% more. Magic, psionics and M.D. weapons do normal damage.', 'Calling (8), Distant Voice (10), Influence the Beast (12), Magic Shield (6), Mend the Broken (10+), Mystic Fulcrum (5), Repel Animals (7), Summon and Control Animals (125, working animals only), Tame Beast (6). Demonic curses: none.', 'None', '6 ft (1.8 m)', '300-400 lbs (135 to 180 kg)', 'Presumed immortal', 'China; fewer in Russia, India and Southeast Asia', 'Ma T-ou and Pig Demons; yields to anything smarter or stronger without real loyalty; serves the Yama Kings, Demon Lords, dark gods, sorcerers and evil dragons when let loose to fight or to drive slaves', 'Mortals, whom it would beat and enslave; Demon Quellers above all. Resents great warriors, brawls with Falcon Demons and despises Fox Spirits, Monkey Spirits, Fox Faeries and other tricksters', NULL, 'A bull-headed labourer and bruiser, slow-witted, tireless and easily tricked, that flies into a rage when mocked. It bullies slaves and captives for sport.', 'Rifts World Book 24: China 1 p.99-100'),
('pig-demon', 'Pig Demon', 'demon', 'rifts', 0, 'Anarchist (15%), Miscreant (60%), Diabolic (20%) or Aberrant (5%)', '{"IQ":"1D6+7","ME":"1D6+10","MA":"1D6+10","PS":"1D6+24","PP":"1D6+12","PE":"1D6+18","PB":"1D6","Spd":"1D6+9"}', NULL, NULL, '2D4x10+PE', '1D6x10+34', '4D6+ME', 'Race: a lesser demon. P.S. is Supernatural. Spd is doubled as a pig. Equivalent level 1D4. 60% are male. It gives up, bargains or runs once its M.D.C. is under 40%. Killed at 20 M.D.C. below zero.', NULL, 10, '{"attacks":4,"strike":2,"parry":3,"dodge":1,"disarm":2,"pull":1,"roll":1}', 'A spell counts as two attacks. +1 save vs all magic, +3 save vs Horror Factor, +2 save vs possession. Peasant tools only (broom, rake, hoe, shovel, sickle, pitchfork, hammer, frying pan and the like): +2 strike, +3 parry, +4 disarm, +1 strike thrown. Never a gun; perhaps a magic staff, hammer, mace or axe.', 'Speaks all languages, reads none. Animal Husbandry 50%, Art 50%, Basic Math 70%, Dance 60%, Find Contraband 60%, Gambling 60%, Gardening 65%, Gemology 50%, Land Navigation 40%, Prospecting 45%, Streetwise 44%, Swim 60%, two Rogue and two Domestic skills of choice 60%. Skills do not improve.', 'Good sight, nightvision 300 ft (91 m), sees the invisible. Immune to S.D.C. weapons, disease, bad food and poison. Bio-regeneration: 1D6 M.D. each melee round (double at ley lines or wherever negative energy gathers). Sleeps five hours in 24. Pig form: a large white pig with glowing yellow eyes, 4 ft (1.2 m) at the shoulder and 8 ft (2.4 m) long. As a pig it belches a stench, one attack each: roll 15 or higher or retch, losing two actions and initiative that round and -1 on all combat bonuses the next. Knows food by smell, 80% +2% per level, and tracks by smell, 50% +2% per level, +10% on a strong scent. Keeps contacts among the thieves, smugglers, fences, Goblins and spirits of wherever it lives. VULNERABILITIES: it lives on rumour, and only 1D4x10% of what it repeats holds any truth. M.D. fire, magic and plasma included, does double damage; S.D.C. fire none. Gossip and stories distract it (+20% to prowl past). It never fights to the death. Magic, psionics and M.D. weapons do normal damage.', 'Escape (8), Featherlight (10), Lantern Light (1), Mystic Alarm (5), Mask of Deceit (15), Watchguard (10), and two spells of choice from Invocation levels 1-3. Demonic curses: none.', 'Minor Psychic: Mind Block (4), Remote Viewing (10), Total Recall (2)', '5-6 ft (1.5 to 1.8 m)', '250-400 lbs (112.5 to 180 kg)', 'Presumed immortal', 'China; far fewer in Southeast Asia and India', 'Other Pig Demons are its only true friends; it will serve humans, D-Bees, Shifters, greater demons, the Yama Kings, dragons and dark gods, and pretends to like Goat, Horse and Ox demons', 'It hates no one: most people are marks to trick and cheat, and the weak are there to bully', NULL, 'A fat, pig-headed demon that everyone takes for lazy and dim, and which uses that to eavesdrop, trade secrets and steal. It avoids a real fight and loots its master when his luck turns.', 'Rifts World Book 24: China 1 p.100-102'),
('yang-ching', 'Yang Ching', 'demon', 'rifts', 0, 'Miscreant (20%), Diabolic (30%) or Aberrant (50%)', '{"IQ":"1D6+8","ME":"1D6+12","MA":"1D6+12","PS":"1D6+24","PP":"1D6+18","PE":"1D6+16","PB":"1D6+8","Spd":"1D6+30"}', NULL, NULL, 'PEx10', 'PEx5', NULL, 'Also known as the Goat Demon. Race: a lesser demon. P.S. is Supernatural. Spd is about 20 mph (32 km). Most wear partial body armor of 1D6x10+12 M.D.C. Equivalent level 1D6. Male. Killed at 30 M.D.C. below zero.', NULL, 13, '{"attacks":6,"initiative":3,"strike":3,"parry":2,"dodge":1,"disarm":3,"pull":4,"roll":2}', 'A spell counts as three attacks. +1 save vs all magic, +6 save vs Horror Factor, +3 save vs possession. Any ancient hand weapon: +2 strike, +1 parry; the long spear: +3 strike, +2 parry, +2 disarm, +4 strike thrown. Guns and modern weapons with no bonus. In fog or mist it is invisible and foes are -6 to strike, parry and dodge.', 'Speaks all languages, reads none. Basic Math 80%, Climb 90%/80%, Find Contraband 60%, Land Navigation 90%, Lore: Demons and Monsters 80%, Lore: Psychics and Psionics 70%, Military Etiquette 90%, Recognize Weapon Quality 90%, two Espionage or Military skills of choice 50%. Skills do not improve.', 'Sharp sight, nightvision 1000 ft (305 m), sees the invisible. Leaps 20 ft (6.1 m) up and 50 ft (15.2 m) across; takes steep slopes and narrow mountain paths at a full run, 95%. Immune to S.D.C. weapons other than silver, and to disease; heat and cold do half damage. Bio-regeneration: 2D6 M.D. each melee round (double at ley lines or wherever negative energy gathers). Sleeps five hours in 24. Turns invisible in fog or mist without effort. It never forgets a defeat. VULNERABILITIES: S.D.C. silver does its damage as M.D. Rune weapons and magic weapons of wood do double damage.', 'Armor of Ithan (10), Barrage (15), Blinding Flash (1), Breathe Without Air (5), Call Lightning (15), Crushing Fist (12), Deflect (10), Energy Bolt (5), Fire Bolt (7), Frequency Jamming (15), Frostblade (15), Heal Self (20), Lantern Light (1), Light Target (6), Magic Shield (6), Mystic Alarm (5), Power Bolt (20), Power Weapon (35). Demonic curses: Rags.', 'None', '7 ft (2.1 m)', '300 lbs (135 kg)', 'Presumed immortal', 'China; fewer in the forests and mountains of Russia, Mongolia and Japan', 'Respects power and ruthlessness; serves the Yama Kings, Demon Lords, dark gods and evil dragons', 'Mortals, whom it would see enslaved. It respects great heroes, warriors, fighting monks and Demon Quellers, and seeks them out to test them', NULL, 'A goat-headed, goat-legged demon warrior made for war and slaughter, which takes a terrible revenge for any defeat. It fights best with a long spear and vanishes in fog.', 'Rifts World Book 24: China 1 p.104-105');
