-- Rifts World Book 24: China 1 - its bestiary and its notable NPCs.
-- 10 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~061-china-1-lesser-demons.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.




-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 10 creatures are in' AS assertion, count(*) AS got, 10 AS want
  FROM creatures WHERE slug IN ('chuan-ti', 'falcon-demon', 'fox-faerie', 'headless-one', 'long-armed-giant', 'ma-tou', 'monkey-wolf', 'ox-head-demon', 'pig-demon', 'yang-ching');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('chuan-ti', 'falcon-demon', 'fox-faerie', 'headless-one', 'long-armed-giant', 'ma-tou', 'monkey-wolf', 'ox-head-demon', 'pig-demon', 'yang-ching');
SELECT 'the creatures carry 57 attacks' AS assertion, count(*) AS got, 57 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('chuan-ti', 'falcon-demon', 'fox-faerie', 'headless-one', 'long-armed-giant', 'ma-tou', 'monkey-wolf', 'ox-head-demon', 'pig-demon', 'yang-ching');

